def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Find a disjoint tiling by 2x2 squares and L-triominoes. Prefer squares.
    squares = []
    for r in range(h - 1):
        for c in range(w - 1):
            cells = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if cells <= occupied:
                squares.append(cells)

    # Select squares so that leftover cells can be covered by L-triominoes.
    def tile(rem, chosen):
        if not rem:
            return chosen
        r, c = min(rem)
        # Try a square containing the first remaining cell.
        for sq in squares:
            if (r, c) in sq and sq <= rem:
                ans = tile(rem - sq, chosen + [(sq, 1)])
                if ans is not None:
                    return ans
        # Try every L triomino containing the first remaining cell.
        for rr in range(max(0, r - 1), min(h - 1, r) + 1):
            for cc in range(max(0, c - 1), min(w - 1, c) + 1):
                block = {(rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)}
                if (r, c) not in block:
                    continue
                for missing in block:
                    tri = block - {missing}
                    if tri <= rem:
                        ans = tile(rem - tri, chosen + [(tri, missing)])
                        if ans is not None:
                            return ans
        return None

    pieces = tile(occupied, [])
    if pieces is None:
        return grid
    for cells, kind in pieces:
        if kind == 1:
            color = 1
        else:
            rr = min(r for r, c in cells)
            cc = min(c for r, c in cells)
            missing = kind
            # L orientation colors inferred from demonstrations.
            rel = (missing[0] - rr, missing[1] - cc)
            color = {(0, 0): 2, (0, 1): 4, (1, 0): 3, (1, 1): 3}[rel]
        for r, c in cells:
            out[r][c] = color
    return out
